# -*- coding: utf-8 -*-
"""一键验证 · 默认档（静态验证，秒级）—— 闸 2 的声明侧十项检查。

怎么跑（在仓库根，只许用仓库内 venv 的 python，只用标准库）：

    cd /Users/hekunhua/Documents/Agent/PHP/系统工程平台V1 && . ./构建环境/进入.sh
    python 构建装配/一键验证/一键验证.py            # 默认档：静态验证（无实测）
    python 构建装配/一键验证/一键验证.py --自测      # 自测：故意造违规样本，断言抓得住
    python 构建装配/一键验证/一键验证.py --缺口      # 打印「检查项本身的洞」清单（不改判定）

退出码：全过（无失败、无未判）= 0；否则 = 1（供 shell 与 CI 用）。

输出（严格照此形状，全过时不打印空的失败段）：

    通过 <N> 项 · 失败 <M> 项 · 耗时 <毫秒> ms

    失败逐条：
    - <哪一项检查> ｜ <哪个文件:哪个键> ｜ 缺什么：<具体> ｜ 为什么不能自愈：<具体>

N / M / K 的口径：**按检查项计**（N + M + K ≥ 17 = §九 十项 + 七项新裁定；
同一条判据可以既有真红、又有空集的子判据，所以这个和可能 > 16）。
同一项检查下可能有多条违规明细，明细逐条列出，但该项只计一次失败。

三元读数（依据 `项目文档/设计文档/判据的可信性.md`）：

- **通过** = 扫描面非空 · 两次运行读数一致 · 无真红 · 样本成对。
- **失败** = 两次运行都报同一条 ⇒ 真红（`同一条判据连跑两次都红才算红`）。
- **未判** = 扫描 0 项（对象不存在）· 或子判据的对象是空集 · 或该判据缺反向/正向样本。
  **空集不算通过**（空集算通过就是假绿）。
- **疑似瞬时** = 只在其中一次运行里出现 ⇒ 不当阻断（分类标 `疑似瞬时`）。

判不了的一律进「未判逐条」（不是默默放过、也不是假绿）：判据在、但它声称覆盖的东西是空集时，
`缺什么` 会说清「扫描 0 项」并给出扫描面。`--缺口` 里另有汇总。

十项检查（逐条抄自 契约声明/格式说明.md 第九节，一字不少）：

  | # | 检查 | 依据 |
  |---|---|---|
  | 1 | 编号与文件名一致 | 文件名即编号 |
  | 2 | 编号不重复 | 文件名天然唯一，另查 JSON 内字段与文件名一致 |
  | 3 | 编号不在作废号表里（**只比同空间**的号：作废行带 `号空间`） | `作废号表.json` · `号段图.json` 的「四个号空间互不相通」· `字段名册与引用方式.md` §五 的「类型标签 … 与上面四个不通」 |
  | 4 | 编号落在自己那一层号段内 | `号段图.json` 的 `能力号段`（布局）；另查 `平台声明.json` 的 `能力号段`（占用）⊆ 布局 |
  | 5 | 参数类型都在类型表里 | `类型声明/` |
  | 6 | 返回类型在类型表里（或为 0） | 同上 |
  | 7 | `可抛错误码` 每一项都在错误码表登记，三项业务登记项齐全，且冗余登记项 `段位 == 码 // 1000` | `错误码表/` |
  | 8 | 通知号落在对应方向的号段内 | `通知号段/` |
  | 9 | 冻结登记三键齐全 · 落点存在且是**单个**落点 · 日期成形 | 冻结登记 |
  | 10 | 生成物与 JSON 一致（指纹比对） | 生成关系 |

  这十项全部是**纯数据比对**，不编译、不启动、不跑用例——所以秒级。

另有七项新裁定落成判据（不在 §九 表内，但同属闸 2 声明侧）：

  | # | 检查 | 依据 |
  |---|---|---|
  | 11 | 拓扑唯一性：每类出入口恰好一个（6 条子判据） | `项目文档/设计文档/全局连接器与网关.md` 第四节 |
  | 12 | 边界纪律：每个扩展恰好 1 个接缝导出 · 边界里 0 业务判断 · 0 状态 | `跨语言适配/边界协议/边界协议.md` 第四节 |
  | 13 | 常量表：同名常量不许在别处再定义 + 每条常量在生成物里有对应常量或标「未定数」 | `契约声明/常量表.json` 的判据 |
  | 14 | 元判据：每条判据都有反向样本与正向样本 · 三元输出 · 声明了扫描面 · 一次运行里都被执行过 | `判据的可信性.md` 第六节 |
  | 15 | 禁按行号引用：引用一律按符号（源码 `路径::符号名` · 文档 `路径 §节名`） | `项目文档/未完成事项.md` #156 |
  | 16 | 底座不认识扩展：底座代码面里 0 处出现任何扩展的名字 | `README.md` §五「底座与扩展」硬边界 1 · `扩展装载/扩展根声明.json` 文件头 |
  | 17 | 临时件不落源码树：`_临时_` 前缀的目录/文件一律落 `/tmp` | `README.md` §十.1 · `项目文档/未完成事项.md` #204 |

**两处检查名在本实现里改成了它真查的东西**（不是改判据，是改措辞——判据覆盖不到它声称覆盖的东西时，
留着旧说法就是假绿）：

- **第 4 项**依据换成 `契约声明/号段图.json`（全平台布局）。`平台声明.json` 的 `能力号段` /
  `通知号段` 是**本声明占用**，不是布局（§二 ★「`能力号段` 在这两个地方不是一回事」）。
  占用段形状只有 `{起, 止}`、**没有 `归属`**，不许再报「缺 归属」。
- **第 9 项**改叫「冻结登记：三键齐全 · 落点存在 · 日期成形（形状是否被改，判不了）」。
  原因已登记为 `冻结登记.json` 的待办旁路：`冻结项` 只有 `名称/内容/落点` 三键、`内容` 是散文、
  没有形状指纹，所以「冻结的形状有没有被悄悄改动」**判不了**；旧说法「冻结项未被改动」是假绿。

本实现的落点与口径（改这里之前先读）：

- **编号目录**（文件名即编号）共四个，十项里的 1/2/3 对四个目录全扫：
  `类型声明/`（字段 `类型标签`）· `能力声明/`（字段 `编号`）·
  `错误码表/`（字段 `码`）· `通知号段/`（字段 `通知号`）。
  这四个是**四个独立命名空间**（格式说明 §二 ★），跨目录同号不算重复。
- **第 4 项**：编号归属查 `号段图.json`（能力编号查它的 `能力号段`、通知号查它的 `通知号段`）；
  号段图自身也要合法（每段带 `归属` · 起≤止 · 两两不相交 · 并集无洞），
  **四节都要在**（能力号段 · 通知号段 · 资源号段 · 错误码段位图）；错误码段位图另判
  「段位 0–9 各一条」+「同一层在能力号段与段位图里必须同归属（号段即归属）」。
  **新增断言：占用 ⊆ 布局**——`平台声明.json.能力号段`/`通知号段` 的每一段必须落在 `号段图.json`
  对应命名空间的并集内（否则「本声明占了一段平台没划给它的号」）；
  `平台声明.错误段位表` 的每个段位也必须在 `错误码段位图` 里。
  资源号段的命名空间边界没有明文 ⇒ 只判不相交、不判无洞（见 `--缺口`）。
  类型标签与错误码不在号段制内（§十 待裁），只做派生自 lib.rs/§五 的范围约束，见 `--缺口`。
- **第 7 项**（码 ≠ 段位）：`码` = 完整 4 位号 = 文件名；`段位` = 码的首位十进制数字，
  必须等于 `码 // 1000`。登记项**分两类**（§五）：**三项业务登记项**（`可重试` · `可自愈` ·
  `需人工`，人必须给）+ **一项冗余登记项**（`段位`，可从码导出，故意写出来让验证面交叉比对抓错）。
  另做 lib.rs 平台信息.错误码表 注释定死的双向交叉比对：`段位表 == 错误码表里各码的段位集合`。
- **第 8 项**：`方向` **只取 `下行` / `上行` 两个值**——它是协议方向，不是号段名（§六）。
  号段由**通知号本身**决定：`1–999` 下行段 · `1000–1999` 上行段 · `2000–2999` 生命周期段；
  **生命周期段里两个方向都合法**（`2000..2003` 是 `下行`、`2015` 是 `上行`）。
- **第 9 项**：除「三键齐全 · 落点存在 · 日期成形」外，**落点必须是单值**，写法二选一：
  `相对路径` 或 `相对路径::符号名`，**不许复合**（不许 `甲.md · 乙目录`）——README 第八节定死了。
- **第 11 项（拓扑唯一性）**：六条子判据逐条数，依据 `全局连接器与网关.md` 第四节 ——
  ①对外监听恰好 1 处 ②导出的 C ABI 边界恰好 1 组（数 `export_name` / `no_mangle` 属性，
  **不是**数 `extern "C"`——没导出属性的符号会被 mangled，不算导出）③调用内核入口 `载入` 恰好 1 处
  ④资源出入口恰好 1 处 ⑤层间边：不许反向 · 不许跳层（允许集合逐条抄 README 第六节的表）·
  同一对层之间不许有两个目标包 ⑥`前端呈现/` 里恰好 0 处解析 / 生成 / 校验逻辑。
  扫描排除 `构建装配/` 与 `开发工具/`（README 第六节：构建装配「只读契约、只收扩展，**不参与运行**」，
  验证器与生成器是开发期工具，不是平台的一条腿）。
- **第 13 项（常量表）**：形状（名唯一 · 值/类型一致 · `null` = 未定数）+ **同名常量不许在别处再定义**
  （全仓 `const <常量名>`，排除 `常量表.json` 与生成物 —— 这是「两处以上引用就必须进常量表」的
  可判落点）+ 按值匹配那条**判不了**（缺「字面量 → 常量」的归属标注），照实报读数。
- **第 10 项**：生成物落点 `契约声明/src/声明数据.rs`、生成器落点
  `构建装配/形态装配/生成声明.py`（格式说明 §八）。指纹闸按 §八 的原话交给生成器自己
  的 `--检查` 模式（重新生成到内存、与落盘件逐字节比对）——验证面不另写一套哈希，
  免得造出第二个「生成物新鲜度」判据。**手写 `平台信息` 的判据按待办旁路的收窄口径实现
  （见下），另按 §八 把装载入口里手写的底座常量（标识串 · 名称 · 声明格式号 · 三个版本三元组）
  与 `平台声明.json` 逐项比对。**
  （源文件指纹的逐文件口径见生成器 `源指纹()`：`sha256(文件字节).hexdigest()[:16]`。）

**第 10 项 · 手写 `平台信息` 的判据（收窄范围 + 加约束，不是豁免）**
（依据：`冻结登记.json` 待办旁路「『手写 static 平台信息 即违规』这条判据没有限定范围」）

判据从「任何一处」收窄成「**底座的声明只有一个来源**」，分三条子断言：

- **A 非测试区不许出现手写的 `平台信息` 构造点**：每一处 `平台信息 { … }` 构造点，若不在
  `#[cfg(test)]` 区内、且它的**声明数据字段有手写的** ⇒ 违规。
  （判的是「声明只有一个来源」，不是「`static` 这个关键字」⇒ 比只认 `static` 更严：`const` ·
  `let` · 函数内构造都在内。生成物自身除外——它的字面量就是那个唯一来源。）
  **「手写」的口径 = 声明数据字段的值不是 `声明数据::…`**。这样读是必须的：生成物的收口说明
  要求**保留** `static 底座存储` 这个构造点、只把字段换成 `v1_contract::声明数据::..`
  （见 `契约声明/src/声明数据.rs` 的「引用方怎么接」）；若把「手写」读成「构造点存在即违规」，
  收口做完这条也永远红 ⇒ 判据自己写错。
- **B 声明数据字段必须来自生成物**：同一处构造点的**声明数据字段**（`声明格式号` · `目标字宽` ·
  `标识串` · `实现版本` · `要求宿主版本` · `要求内核版本` · `名称` · `说明` ·
  `能力号段` · `通知号段` · `错误段位表`）逐字段列出谁没引用生成物。
  （结构性字段 `保留` · `状态位` · `类型表` · `命令表` · `函数表` · `常量表` · `通知函数` ·
  `依赖清单` 不判——它们的内容另有来源。）
- **C 测试夹具另加两条更严条件**：`#[cfg(test)]` 区内的构造点算夹具，必须 ①**具名**
  （找不到所属 `static`/`const`/`fn` ⇒ 违规：匿名夹具没法判②）②**不许被生产代码引用**
  （夹具名在任一文件的**非测试区**出现 ⇒ 违规）。

并发（这是秒级的实现手段，不是可选项）：读文件与跑检查都用
`ThreadPoolExecutor(max_workers=32)`；**没有任何一处串行 for 循环跑全量**。
"""

from __future__ import annotations

