# ── 拓扑唯一性（项目文档/设计文档/全局连接器与网关.md 第四节）──
# 判据 5（已改）：**不许跳层 · 不许反向**。每条依赖边必须连接分层链上**相邻**的两层，
# 且方向自上层向下层。原写法「同一对层之间不许有两条边」是空转的（层对只有一个、恒为 1），
# 已由实测反证推翻（适配器依赖运行内核的 3 个包 = 一条路，按目标包算会误报成 3 条边）。
