公共底层 = "契约声明"
# 层在链上的位置（小的在下游）；用于判「反向」
层序 = {
    "契约声明": 0,
    "运行内核": 1,
    "扩展装载": 2,
    "扩展根": 2,
    "跨语言适配": 2,
    "对外接口面": 3,
    "前端呈现": 4,
    "构建装配": 3,
}
# 边界协议（跨语言适配/边界协议/边界协议.md 第三节 · 第四节）
接缝符号 = "GetPlatformInfo"
对外边界符号 = ("平台_取接口描述", "平台_调用", "平台_释放值")
导出名模式 = re.compile(r'#\[(?:unsafe\()?export_name\s*=\s*"([^"]+)"\)?\]')
导出属性模式 = re.compile(r"#\[(?:unsafe\()?export_name|#\[no_mangle\]")
扩展根三类 = ("原子支持库", "组合模块库", "技能封装库")
# README §五「底座与扩展」三条硬边界之一：「底座不认识任何扩展 —— 底座里不许出现任何扩展的
# 名字、路径或特例分支」。判据 ⑯ 就是这条的判据（此前**一条判据都没有**，
# 所以 `对外接口面` 与前端里点名的扩展名一路活到 2026-09-27 才被扫出来）。
#
# 扫描面 = 底座代码面：底座三棵树 + 接缝（`扩展装载/`，它只规定「扩展长成什么样」）
# + 前端（前端零逻辑：能力名一律取自 `GET /接口` 的实时应答）。
# 排除三类**按设计必须认识扩展**的：
#   · `扩展根目录/` —— 扩展本体自己；
#   · `测试验证/` `构建装配/` `开发工具/` —— 端到端门禁与工具，它们验的就是具体扩展
#     （`Cargo.toml` 的 `exclude` 那条 path 依赖同理，注释里已写明「它不是底座的一条腿」）；
#   · `契约声明/` —— 数据面：`号段图.json` 声明号段布局、`冻结登记.json` 记冻结项，
#     两者按设计都写扩展号段与编号（那是布局与账本，不是「认识某个扩展」）。
# 只查**扩展名**这一形：`扩展根目录/<层>/<扩展名>` 的具体路径必然含扩展名 ⇒ 一并被抓；
# 而 `导出目标.js` 那种 `<扩展名>` 占位的通用说明不含真名 ⇒ 不误报。
#
# **诚实边界**：抓的是「点名」。只写编号不写名字的耦合（例如前端把编译链 `1101→1102→…`
# 写成数组）抓不到 —— 那要靠「前端不硬写任何编号」这条纪律，判据面覆盖不到它。
底座代码树 = ("运行内核", "跨语言适配", "对外接口面", "扩展装载", "前端呈现")
底座代码面排除 = (
    "扩展根目录/", "测试验证/", "构建装配/", "开发工具/", "项目文档/",
    "契约声明/", "工程缓存/", "target/",
)
边界业务判断模式 = re.compile(r"if\s+(?:号|能力号|编号)\s*==|match\s+(?:号|能力号|编号)\s*\{")
边界状态模式 = re.compile(r"(?m)^[ \t]*(?:pub(?:\([^)]*\))?[ \t]+)?static[ \t]+")
边界目录前缀 = "跨语言适配/"
# 目录前缀 → 层
顶层目录到层 = {
    "契约声明": "契约声明",
    "运行内核": "运行内核",
    "扩展装载": "扩展装载",
    "跨语言适配": "跨语言适配",
    "对外接口面": "对外接口面",
    "前端呈现": "前端呈现",
    "构建装配": "构建装配",
    "扩展根目录": "扩展根",
}
# 对外监听：**监听调用点**，不是类型出现处。
# 为什么按调用点读：实测撞到过 `对外接口面/调用接口面/src/网关.rs` 读成 6 处——
# 多出来的是 `use std::net::{TcpListener, TcpStream};`（导入）、`监听: TcpListener,`（字段声明）
# 这类**类型提及**。类型提及不是监听点；`监听模式` 定义处下面的注释自己写的是
# 「恰好 1 处；那一处就是本文件的 `TcpListener::bind`」⇒ 口径本来就是调用点。
# 只保留真正会**开一个监听/服务**的调用形。
监听模式 = re.compile(
    r"(?:TcpListener::bind|UdpSocket::bind|Server::bind|hyper::Server::bind|"
    r"\.bind\s*\(|\.listen\s*\(|\.serve\s*\(|createServer|"
    r"app\.run\s*\(|uvicorn|HTTPServer|axum::serve|warp::serve|actix_web::HttpServer)"
)
# 导出符号：这两个属性才把符号导出（光写 `extern "C"` 是被 mangled 的，不算导出）
导出模式 = re.compile(r"#\[(?:unsafe\()?export_name|#\[no_mangle\]")

# ── 判据 ⑮ 的三种「按行号引用」形状（现场实测到的形状，不止一种）──
#   形一：`路径.扩展名:行号`，可带区间 `…:起-止`（如 `底座静态声明.rs` 那处、`扫实现.py` 那两处自引）
#   形二：`第 N 行` / `第 N/M 行`（**md 行号引用同罪** —— 与形一是同一失效模式）
#   形三：`L` 前缀的行号记法 —— **只认「`L` + 起–止 两个数字」的区间形，与后面紧跟「行」的**：
#         单个 `L` + 一个数字与字段名（实测 `u32 L` + 数字 + `+库名` 那种）在文本上分不开，
#         认它会变成假红工厂（同 §一 #5「不许设会把 `值`/`码`/`槽` 一起判红的硬门槛」那条教训）。
# 形一把**被引路径**也捕获下来（组 1）——豁免要按**这一条引用自己的路径**判，
# 不能按整行前缀判：同一行里前面的语料件会把后面的代码件一起豁免掉（实测撞到过）。
# 路径字符类不收空白与反引号 ⇒ 匹配天然被词边界截断，不会跨行。
行号引用_路径 = re.compile(r"([A-Za-z0-9_./\-一-鿿]{1,120})\.([A-Za-z0-9_]{1,8}):(\d+)(?:\s*[-–—]\s*(\d+))?")
行号引用_第几行 = re.compile(r"第\s*(\d+(?:\s*[/、,]\s*\d+)*)\s*行")
行号引用_L前缀 = re.compile(r"(?<![A-Za-z0-9_])L(\d+)(?:\s*[-–—]\s*(\d+))?(?![A-Za-z0-9_])")
# 判据 ⑮ 扫哪些件：`.md` 与 `.py` 是本条裁决点名的两处；`.rs` 里实测也撞到过 ⇒ 一并收
行号引用后缀 = (".md", ".py", ".rs")
# 语料 / 样本件：引它的行是**样本数据内容**，不是代码定位 ⇒ 允许
# （中文扩展名如 `.程序文本` / `.容器` 天然不匹配形一；这里再收易语言的 `.e` / `.ec` / `.fne` 与只读语料根）
语料后缀 = ("e", "ec", "fne")
语料路径片段 = ("只读参考/",)
# 资源出入口：**唯一出入口的形状**，不是一袋同义词（2026-09-25 收窄）。
# 为什么按形状读（依据：项目文档/未完成事项.md #34 · 项目文档/决策记录/2026-09-26_验证面的边界.md §7.2）：
#   原模式 `资源清单|资源派发|资源调用|资源关口|资源声明表|资源表` 是**同义词袋**，且命中
#   **任意位置**（文档串 / 类型名 / 调用点 / 私有助手）都算 ⇒ 换个命名、或别处写一句同义词就红。
#   现在只认**定义形**，且参数表**恰好**是 项目文档/设计文档/资源网关口.md §四 冻结的访问形状
#   `资源调用(资源号, 操作号, 输入槽表) -> 输出槽表 | 结构化错误` 的三个角色（无多余参数）：
#     · 不认函数名 ⇒ 改名不再红（#34 的第一条抱怨）；
#     · 只认 `fn …(` ⇒ 文档串 / 调用点 / 类型提及不再红；
#     · 参数表恰好三个角色 ⇒ 私有助手（多一个参数）不算第二处。
# 残留：三个角色名仍是中文标识符——本仓全是中文标识符，无法避免；但它取自 §四 的**冻结形状**
#   （与 `对外边界符号` 那三个中文名同一性质），不是同义词袋。彻底的结构约束是「把唯一出入口
#   做成唯一构造口（类型）」，见 验证面的边界.md §7.2「结构约束」一档。
资源出入口形 = re.compile(
    r"\bfn\s+[^\s(]+\s*\(\s*(?:&\s*(?:'[^,]*\s*)?(?:mut\s+)?self\s*,\s*)?"
    r"资源号\s*:[^,]+,\s*操作号\s*:[^,]+,\s*输入槽表\s*:[^)]+\)\s*->"
)
# 前端不许有的逻辑 —— **语义判**（2026-09-27 收窄：判「它有没有对内容作出判断」，不判「出现了哪个词」）。
# 依据：项目文档/未完成事项.md #176（裁决）· 项目文档/设计文档/接口面形状.md §五（三条不许）。
#
# 原模式 `JSON\.parse|JSON\.stringify|校验|解析|生成|validate|parse\(` 是一袋**词**，
# 于是把**传输必需的编码**判成了违规：`前端呈现/网页应用/取接口.js` 里的 `JSON.stringify(文本)`
# 只把编辑区文本编成 JSON 字面量（不改内容 · 不看内容），却被数成一处「处理程序」。
# （实测更正 #176 的一处读法：命中处是**代码里的那个调用**，不是注释 —— 注释早被 `去字面量` 剥掉；
#  那条注释只是在**解释它不是违规**，所以整件事看起来像「辩解被判成了罪证」。）
#
# 口径（三段）：
#   · **解析 ⇒ 禁**：`JSON.parse` 把文本变成值 = 对内容作出判断 ⇒ 绕过网关直连声明，
#     前端与网关两套判定必然漂移（判据 6 的本意）。
#   · **序列化 ⇒ 允许**：`JSON.stringify` 只把文本**编码成 JSON 字面量**（转义引号/换行/反斜杠），
#     不改一个字节、不看内容、不认关键字——传输必需，不是处理程序（`前端呈现/说明.md` §三.1）。
#   · **其余同原则**：判断动词的**调用形** ⇒ 禁；纯搬运 / 编码 / 拼接 ⇒ 允许。
#   「调用形」是关键：裸词会把注释与同义串一起判红（实测），而 `校验(x)` 这种**调用**才是判断。
# 残留（如实登记，见 --缺口）：`.html` 内联 `<script>` 不在扫描面内；正则字面量的**非调用**用法认不出。
前端逻辑模式 = re.compile(
    r"JSON\s*\.\s*parse\b"  # 解析 JSON 文本（裁决点名的那一个）
    r"|\bDOMParser\b|\bparseFromString\b"  # 解析 HTML / XML 文本
    r"|\beval\s*\(|\bnew\s+Function\s*\("  # 动态求值：对内容作出判断的另一面
    r"|\bnew\s+RegExp\s*\(|\.[ \t]*(?:test|exec)\s*\("  # 正则判断
    r"|[\w$]*(?:解析|校验|验证|生成|判断|检查|转换"  # 判断动词的**调用形**
    r"|parse|validate|generat|convert|regex|正则)[\w$]*\s*\("
)

# 产物头必须标（格式说明 §八）：生成物声明 · 源文件清单 · 源文件指纹 · 生成器路径。
# 这里按「四件事有没有」判，不按字面键名判——生成器怎么措辞是它的自由，
# 但四件事缺一件，后人就无从判断该改源还是改产物。
生成物头标要求 = (
    ("生成物声明", lambda 头: ("生成物" in 头) and ("禁手改" in 头)),
    ("源文件清单", lambda 头: bool(re.search(r"^//.*契约声明/.*\.json", 头, re.M))),
    ("源文件指纹", lambda 头: "指纹" in 头),
    ("生成器路径", lambda 头: "生成器" in 头),
)

# 平台信息 里属于「声明数据」的字段（值必须来自生成物 声明数据::…）。
# 其余字段（保留 · 状态位 · 类型表 · 命令表 · 函数表 · 常量表 · 通知函数 · 依赖清单）
# 是结构性字段：它们的内容另有来源，不在这里判。
声明数据字段 = (
    "声明格式号",
    "目标字宽",
    "标识串",
    "实现版本",
    "要求宿主版本",
    "要求内核版本",
    "名称",
    "说明",
    "能力号段",
    "通知号段",
    "错误段位表",
)

# 占用段（平台声明.json 的 能力号段 / 通知号段）的形状：只有 起/止，没有 归属
占用段键 = ("起", "止")
# 布局段（号段图.json）的形状：起/止 + 归属（「每一段归谁」就是它存在的理由）
布局段键 = ("起", "止", "归属")

# 扫描后缀：全仓扫文件时收哪些后缀（一个地方定义，别处都引它）。
# **实测撞到的洞**：原来这里只收 (".rs", ".json", ".toml", ".md", ".py", ".sh")，
# 而下面 代码后缀 里写着 ".ts" / ".vue" / ".js" —— 于是 `前端呈现/` 下的 .ts 文件
# 从来没被读进内存，判据 6（前端零逻辑）永远是空集，拓扑扫描也看不见前端那一层。
# 正向样本（干净合成仓）里 `前端呈现/网页应用/索引.ts` 就是这么被漏掉的（实测）。
扫描后缀 = (
    ".rs", ".json", ".toml", ".md", ".py", ".sh",
    ".ts", ".tsx", ".js", ".jsx", ".vue", ".svelte",
    ".go", ".java", ".c", ".cpp", ".h", ".hpp",
)
# 代码后缀：扫描后缀里除声明 / 文档 / 构建清单之外的那些（判据只对代码有意义）
代码后缀 = tuple(
    s for s in 扫描后缀 if s not in (".json", ".toml", ".md", ".sh")
)
# Rust 类判据的收窄扫描面（未完成事项.md #37 裁决）：**Rust 类只收 `.rs`**。
# 为什么：Rust 类判据（拓扑的监听/载入/资源/导出 · 边界纪律 · 常量表）用的词法是 Rust 的
# （`//` 注释 · `#[…]` 属性 · `::` 路径），拿它去扫 `.py` / `.ts` 会**跨语言借词法**：
# 实测 `.py` 的注释是 `#`，`去字面量` 剥不掉 ⇒ 注释里的词也算命中（见 ⑪-6 的实测）。
# 前端类另有一条扫描面（`前端呈现/**` 的 `.js/.jsx/.ts/.tsx/.vue/.svelte`）。
# 注意：⑯ 底座不认识扩展**不是** Rust 类（它要抓前端里的扩展名）⇒ 不套这条。
Rust后缀 = (".rs",)
# 扫描全仓时跳过的目录（生成物/缓存/参照物，不参与判定）
跳过目录 = {"构建环境", "只读参考", ".git", "__pycache__", "node_modules", "target"}

# 临时件命名约定（未完成事项.md #204）：**临时件一律落 `/tmp`（仓外）**。
# 万一有腿把临时件落在源码树里，约定用 `_临时_` 前缀命名它 ⇒ 扫描面**防御性排除**，
# 不让它把全仓判据打红（实测：临时声明根在树里时 ⑬ 报 9 条、⑮ 报 1 条，全是假红）。
# 纪律本身由 `检查17_临时件不落源码树` 钉住：树里出现 `_临时_*` 即报一条、并指明挪到 /tmp。
# 前缀用下划线开头，与任何正常目录名（README 命名规则：4 字及以上、语义自足）都不撞。
临时目录前缀 = "_临时_"


def 是临时路径(相对键: str) -> bool:
    """路径的**任一段**以 `_临时_` 开头 ⇒ 是临时件（扫描面一律排除）。"""
    return any(段.startswith(临时目录前缀) for 段 in str(相对键).split("/"))

检查名 = (
    "① 编号与文件名一致",
    "② 编号不重复",
    "③ 编号不在作废号表里",
    "④ 编号落在自己那一层号段内（依据 号段图.json）+ 占用 ⊆ 布局",
    "⑤ 参数类型都在类型表里",
    "⑥ 返回类型在类型表里（或为 0）",
    "⑦ 可抛错误码都在错误码表登记，且三项业务登记项齐全、冗余段位与码首位一致",
    "⑧ 通知号落在对应方向的号段内（方向只取 下行/上行）",
    "⑨ 冻结登记：三键齐全 · 落点存在且是单个落点 · 日期成形（形状是否被改，判不了）",
    "⑩ 生成物与 JSON 一致（指纹比对）",
    "⑪ 拓扑唯一性：每类出入口恰好一个（全局连接器与网关 第四节）",
    "⑫ 边界纪律：每个扩展恰好 1 个接缝导出 · 边界里 0 业务判断 · 0 状态（边界协议 第四节）",
    "⑬ 常量表：同名常量不许在别处再定义 + 每条常量在生成物里有对应常量或标「未定数」",
    "⑭ 元判据：每条判据都有反向样本与正向样本 · 三元输出 · 声明了扫描面 · 一次运行里都被执行过",
    "⑮ 禁按行号引用：引用一律按符号（源码 `路径::符号名` · 文档 `路径 §节名`），不按行号",
    "⑯ 底座不认识扩展：底座代码面里 0 处出现任何扩展的名字（README 硬边界 1）",
    "⑰ 临时件不落源码树：`_临时_` 前缀的目录/文件一律落 `/tmp`（README §十.1）",
)

