空话表 = ("需要人工确认", "人工确认", "需要人工处理", "请人工", "待确认", "TBD")

# ════════════════════════════════════════════════════════════════════════════
# 小工具
# ════════════════════════════════════════════════════════════════════════════


def 是整数(值) -> bool:
    """真整数（bool 不算——它是 int 的子类，会把 True 当 1 蒙过去）。"""
    return isinstance(值, int) and not isinstance(值, bool)


def 违规(检查: str, 位置: str, 缺什么: str, 不能自愈: str) -> dict:
    return {"检查": 检查, "位置": 位置, "缺什么": 缺什么, "不能自愈": 不能自愈}


# 判据内部的「子判据空集」通道（判据的可信性.md 第二节：空集是未判，不是通过）。
# 为什么要有它：一条判据常常是好几条子判据合起来的（例：⑪ 有 6 条），
# 其中某一条的对象是空集时（例：`前端呈现/` 下 0 个源文件），
# 整条判据不能报「失败」（那不是违规），但也不能报「通过」（那是假绿）
# ⇒ 走这条通道，进「未判逐条」，与「整条判据的对象为空」并列展示。
未判收集: list = []


def 判不了(检查: str, 位置: str, 缺什么: str, 不能自愈: str) -> None:
    未判收集.append(
        {"检查": 检查, "位置": 位置, "缺什么": 缺什么, "不能自愈": 不能自愈,
         "分类": "缺件或半成品"}
    )


def 相对(仓根: Path, 路径: Path) -> str:
    try:
        return 路径.relative_to(仓根).as_posix()
    except ValueError:
        return 路径.as_posix()


def 段归属标签(段: dict) -> str:
    """号段表 `归属` 里 "：" 前那一段（方向标签 / 层级标签）。"""
    文本 = str(段.get("归属", ""))
    for 分隔 in ("：", ":"):
        if 分隔 in 文本:
            return 文本.split(分隔, 1)[0].strip()
    return 文本.strip()


def 层级标签(文本: str) -> str:
    """归属文案里的**层名**：切掉 "：" · "（" · "——" 之后的一切，再去掉 markdown 粗体标记。

    例：「内核自有（不对外）」→「内核自有」；
        「**核心支持库** —— 语言自身的能力（…）」→「核心支持库」；
        「三方封装 · 系统与环境（按**域**分段，以下同）」→「三方封装 · 系统与环境」；
        「下行：宿主 → 扩展」→「下行」。
    两个号空间（能力号 / 错误码段位）写同一层时，括号与破折号后的注解可以不同，层名必须相同。
    """
    文本 = str(文本)
    for 分隔 in ("：", ":"):
        if 分隔 in 文本:
            文本 = 文本.split(分隔, 1)[0]
    文本 = 文本.split("（", 1)[0]
    for 破折 in ("——", "—", " -- ", " - "):
        if 破折 in 文本:
            文本 = 文本.split(破折, 1)[0]
    return 文本.replace("**", "").strip()


def 扫源文件(仓根: Path) -> list:
    """全仓源码文件（跳过生成物与参照物目录）。"""
    结果 = []
    for 根, 目录表, 文件表 in os.walk(仓根):
        目录表[:] = [
            d
            for d in 目录表
            if d not in 跳过目录 and not d.startswith(临时目录前缀)
        ]
        for 名 in 文件表:
            if 名.endswith(扫描后缀):
                结果.append(Path(根) / 名)
    return 结果


# ════════════════════════════════════════════════════════════════════════════
# ① 并行读（IO 密集 · 按文件分片 · 32 路）
# ════════════════════════════════════════════════════════════════════════════


def 读一个文件(任务: tuple) -> tuple:
    """一个分片的全部重活：读字节 → 解 UTF-8 → 解 JSON。都在这里做，并行跑。"""
    仓根, 路径 = 任务
    键 = 相对(仓根, 路径)
    try:
        字节 = 路径.read_bytes()
    except OSError as 错:
        return 键, {"文本": None, "数据": None, "错误": f"读不动：{错}"}
    try:
        文本 = 字节.decode("utf-8")
    except UnicodeDecodeError as 错:
        return 键, {"文本": None, "数据": None, "错误": f"不是 UTF-8：{错}"}
    数据 = None
    错 = None
    if 路径.suffix == ".json":
        try:
            数据 = json.loads(文本)
        except json.JSONDecodeError as 解析错:
            return 键, {"文本": 文本, "数据": None, "错误": f"JSON 解析失败：{解析错}"}
        if not isinstance(数据, dict):
            return 键, {
                "文本": 文本,
                "数据": None,
                "错误": f"顶层不是对象（是 {type(数据).__name__}）",
            }
    return 键, {"文本": 文本, "数据": 数据, "错误": 错}


def 并行读(仓根: Path, 路径表: list) -> dict:
    任务 = [(仓根, p) for p in 路径表]
    with ThreadPoolExecutor(max_workers=并发度) as 池:
        return dict(池.map(读一个文件, 任务))


def 建上下文(仓根: Path) -> dict:
    契约根 = 仓根 / 契约目录名
    # 一次扫全，按文件分片并行读（读 + 解 UTF-8 + 解 JSON 都在分片里）；
    # 后面所有检查都在内存里做，不再回磁盘。
    契约件 = sorted(契约根.rglob("*.json")) if 契约根.is_dir() else []
    # `rglob` 不走 `跳过目录` / 临时件排除 ⇒ 这里按同一口径再筛一遍
    # （否则落进 `契约声明/` 的临时声明根仍会被读进来，未完成事项.md #204）。
    契约件 = [p for p in 契约件 if not 是临时路径(相对(仓根, p))]
    源件 = [p for p in 扫源文件(仓根) if p.suffix != ".json"]
    文件 = 并行读(仓根, 契约件 + 源件)

    平台 = 解析(文件, f"{契约目录名}/平台声明.json")
    号段图 = 解析(文件, 号段图路径)
    常量表 = 解析(文件, 常量表路径)
    作废 = 解析(文件, f"{契约目录名}/作废号表.json")
    冻结 = 解析(文件, f"{契约目录名}/冻结登记.json")

    编号表 = {}
    目录存在 = {}
    for 目录 in 编号目录:
        目录存在[目录] = (契约根 / 目录).is_dir()
        记录表 = []
        前缀 = f"{契约目录名}/{目录}/"
        for 键 in sorted(文件):
            if not 键.startswith(前缀) or not 键.endswith(".json"):
                continue
            记录表.append(
                {
                    "目录": 目录,
                    "文件名": 键.rsplit("/", 1)[1],
                    "键": 键,
                    "字段": 编号字段[目录],
                    "数据": 文件[键]["数据"],
                    "错误": 文件[键]["错误"],
                }
            )
        编号表[目录] = 记录表

    return {
        "仓根": 仓根,
        "文件": 文件,
        "平台": 平台,
        "号段图": 号段图,
        "常量表": 常量表,
        "作废": 作废,
        "冻结": 冻结,
        "编号表": 编号表,
        "编号目录存在": 目录存在,
        "包到层": 建包到层映射(文件),
        "测试文件集": 建测试文件集(文件),
    }


def 建包到层映射(文件: dict) -> dict:
    """Cargo 包名 → 层。包名里的 `-` 换成 `_`（Rust 的 `use` 用下划线）。"""
    表 = {}
    for 键, 项 in 文件.items():
        if not 键.endswith("Cargo.toml") or 项["文本"] is None:
            continue
        配 = re.search(r"^\s*name\s*=\s*\"([^\"]+)\"", 项["文本"], re.M)
        if not 配:
            continue
        层 = 路径到层(键)
        if 层:
            表[配.group(1).replace("-", "_")] = 层
    return 表


def 路径到层(键: str) -> str:
    头 = 键.split("/", 1)[0]
    return 顶层目录到层.get(头, "")


def 解析(文件: dict, 键: str):
    项 = 文件.get(键)
    return None if 项 is None else 项["数据"]


# ════════════════════════════════════════════════════════════════════════════
# 判据的身份证（判据的可信性.md 第五节 · 第六节）
#
# 每条判据必须成对：反向样本（注入一个该抓的违规 ⇒ 必须报红且报对位置与原因）
# + 正向样本（一份干净输入 ⇒ 必须通过）。缺任一方 ⇒ 该判据「未验证」，
# 它的「通过」不计入通过数。
#
# 扫描面：判据声明它扫哪些路径与文件类型；判据自己的对象数为 0 时报
# 「扫描 0 项」= 未判（空集不算通过）。
# ════════════════════════════════════════════════════════════════════════════

契约_json = ("契约声明/平台声明.json", "契约声明/号段图.json", "契约声明/常量表.json",
             "契约声明/作废号表.json", "契约声明/冻结登记.json",
             "契约声明/{类型声明,能力声明,错误码表,通知号段}/*.json")

# 样本清单：**从实际持有的样本派生**（不手写）——反向样本 = 自测里真有的注入函数，
# 正向样本 = 干净合成仓。手写一份清单等于自证，那就又成假绿了。
样本清单 = set()  # 由 建样本清单() 在文件末尾填


def 建样本清单() -> set:
    出 = {名 for 名, _检查, _注入, _位置 in 自测用例}
    出.add("干净合成仓")
    return 出


