    (检查名[7], 检查8_通知号落在对应方向的号段内),
    (检查名[8], 检查9_冻结登记),
    (检查名[9], 检查10_生成物与JSON一致),
    (检查名[10], 检查11_拓扑唯一性),
    (检查名[11], 检查12_边界纪律),
