def 自检_剥字面量剥序() -> list:
    """`去字面量` / `去注释保串` 剥序缺陷的身份证（反向样本 + 正向样本）。

    为什么单列：这一条不是「判据」，是**判据的解析器**——`判据的可信性.md` §三.5
    「判据的解析器坏了」是假绿来源之一，所以解析器自己也要有反向样本。
    反向样本的形状**就是实测撞到的那一条**：断言消息里写 `码 // 号段类宽度`。
    """
    出 = []
    # 模板里刻意留两个特征：
    #   · `#[cfg(test)]` 块（必须整块剥掉）
    #   · 测试块**之后**还有一个字符串（`"尾部"`）——剥序错时，字符串里那个 `//` 会把
    #     收尾引号一起剥掉，留下一个孤立引号，与它配成一对 ⇒ 中间（含 `}`）整段被抹掉
    #     ⇒ cfg 块的大括号找不到闭合 ⇒ 测试代码漏进生产区。
    模板 = (
        "pub fn 生产() -> u32 { 1 }\n"
        "#[cfg(test)]\n"
        "mod 测试 {\n"
        "    pub fn 夹具() -> u32 { 2 }\n"
        "    pub const 目标字宽: u32 = 64;\n"
        '    pub const 说明: &str = "@串@";\n'
        "}\n"
        'pub const 后一个: &str = "尾部";\n'
        "pub fn 之后() -> u32 { 3 }\n"
    )
    坏 = 模板.replace("@串@", "段位 = 码 // 号段类宽度")
    好 = 模板.replace("@串@", "段位 = 码 除以 号段类宽度")
    净坏, 净好 = 生产区文本(坏), 生产区文本(好)
    出.append(
        (
            "反向样本：字符串里的 `//` 不改变 `#[cfg(test)]` 块的剥离结果",
            ("夹具" not in 净坏)
            and ("目标字宽" not in 净坏)
            and 净坏.count("{") == 净好.count("{")
            and 净坏.count("}") == 净好.count("}"),
            f"含 `//` 的净文里 `夹具` 还在={('夹具' in 净坏)} · `目标字宽` 还在="
            f"{('目标字宽' in 净坏)} · 大括号 {净坏.count('{')}/{净坏.count('}')}"
            f"（不含 `//` 的净文是 {净好.count('{')}/{净好.count('}')}）",
        )
    )
    # 正向样本：注释里含引号也必须整段剥掉，且不许把后面的代码当字符串吞掉
    注释样本 = '// 这是 "引号" 与 /* 这也不是注释 */ 的说明\npub fn 生产() { let _ = 1; }\n'
    净注释 = 去字面量(注释样本)
    出.append(
        (
            "正向样本：注释里的引号被正确剥掉，且不吞掉后面的代码",
            '"' not in 净注释 and "fn 生产" in 净注释,
            f"净文里剩引号 {净注释.count(chr(34))} 个 · 后面的 `fn 生产` 还在="
            f"{('fn 生产' in 净注释)}",
        )
    )
    # 正向样本：字符串里含 `/*` 也不许当块注释（同一个剥序缺陷的另一面）
    块样本 = 'pub const 甲: &str = "a /* b";\npub fn 乙() -> u32 { 1 }\n'
    净块 = 去字面量(块样本)
    出.append(
        (
            "正向样本：字符串里的 `/*` 不当块注释（不吞后面的代码）",
            '"' not in 净块 and "fn 乙" in 净块,
            f"净文里剩引号 {净块.count(chr(34))} 个 · 后面的 `fn 乙` 还在={('fn 乙' in 净块)}",
        )
    )
    # ── #185 承重证明：块注释吃掉换行 ⇒ 其后行号整体前移 ──
    # 反向样本的形状就是实测撞到的那一条：一个 4 行的块注释（含 3 个换行）后面跟一个标记。
    带块注释 = (
        "pub fn 甲() -> u32 { 1 }\n"
        "/*\n"
        " 块注释第一行\n"
        " 块注释第二行\n"
        "*/\n"
        "pub const 标记: u32 = 7;\n"
    )
    原文行 = 带块注释[: 带块注释.find("标记")].count("\n") + 1
    净文行 = 去字面量(带块注释)[: 去字面量(带块注释).find("标记")].count("\n") + 1
    出.append(
        (
            "反向样本：块注释剥掉后，其后 token 的行号必须不变（#185）",
            净文行 == 原文行,
            f"原文里 `标记` 在第 {原文行} 行 · 剥后第 {净文行} 行（要求相等）——"
            f"抹掉换行会让其后行号整体前移 N-1 行",
        )
    )
    # 承重证明（退回一步）：**旧抹法**（换行也换成空格）在同一份注入上必须偏 3 行。
    # 把旧行为在样本里复算一遍，证明这条断言真的在承重（不是恒真）。
    def 旧抹法(文: str) -> str:
        """旧 `抹` 的行为：命中区间内**每一个**字符（含换行）都写成空格。"""
        净 = list(去字面量(文))
        起 = 文.find("/*")
        止 = 文.find("*/") + 2
        for p in range(起, 止):
            净[p] = " "
        return "".join(净)

    旧净 = 旧抹法(带块注释)
    旧行 = 旧净[: 旧净.find("标记")].count("\n") + 1
    出.append(
        (
            "承重证明（退回一步）：旧抹法（换行也抹）在同一注入上必须偏移",
            旧行 != 原文行 and 原文行 - 旧行 == 3,
            f"旧抹法下 `标记` 落在第 {旧行} 行（原文 {原文行}）· 偏移 {原文行 - 旧行} 行（要求 3）——"
            f"证明上一条断言不是恒真",
        )
    )
    return 出


def 自检_整份夹具跳过() -> list:
    """整份夹具（由父文件 `#[cfg(test)] … mod …;` 挂进来的独立文件）必须整份跳过。

    反向样本：把一份**看起来是生产代码**的文件（重定义 常量表 里的常量 + 第二个导出符号）
    用 `#[cfg(test)] #[path = "子/夹具.rs"] mod 夹具;` 挂进来 ⇒ 必须整份跳过（不报红）。
    对照：**去掉**那条挂载声明 ⇒ 同一份文件必须被当成生产代码抓到（证明「跳过」不是空转）。
    形状取自真仓实测：`#[path]` 指向**子目录**、mod 名与文件名**不同**、挂载声明写在
    **兄弟文件**（不是 lib.rs/mod.rs/main.rs）里。
    """
    出 = []
    # 样本里的 Rust 形状**拆开拼**：本文件虽在 `构建装配/`（⑪/⑫ 的扫描面把它排除了），
    # 但「排除工具目录」只是判据面的一条口径，随时可能变；在源码里写一整条
    # 「导出属性 + 引号里的符号名」等于给判据面埋一处假红（实测撞到过同类：
    # `测试验证/契约一致性/扫实现.py` 里的样本被读成一个真导出，连注释里的也算）。
    属 = lambda 内: "#" + "[" + 内 + "]"  # noqa: E731
    夹具文 = (
        "// 整份夹具：自己文件里没有 cfg 测试标记\n"
        "pub const 目标字宽: u32 = 64;\n"
        + 属('unsafe(export_name = "SecondDoor")') + "\n"
        + 'pub extern "C" fn 第二道门() -> usize { 0 }\n'
    )
    键父 = "运行内核/实例状态/src/lib.rs"
    键夹具 = "运行内核/实例状态/src/子/夹具.rs"
    件 = {
        "运行内核/实例状态/Cargo.toml": '[package]\nname = "v1-state"\nversion = "0.1.0"\n',
        键父: 属("cfg(test)") + "\n" + 属('path = "子/夹具.rs"') + "\nmod 夹具;\n",
        键夹具: 夹具文,
    }
    集 = 建测试文件集({键: {"文本": 文} for 键, 文 in 件.items()})
    出.append(
        (
            "反向样本：被 `#[cfg(test)] #[path]` 挂进来的整份夹具 ⇒ 跳过",
            键夹具 in 集,
            f"整份夹具集={sorted(集)}",
        )
    )
    # 对照：挂 vs 不挂 —— 只差父文件里那一行挂载声明
    import tempfile

    def 跑(挂: bool) -> dict:
        with tempfile.TemporaryDirectory(prefix="一键验证夹具对照-") as 临时:
            临根 = Path(临时) / "仓"
            造干净仓(临根)
            for 相对, 内容 in 件.items():
                if not 挂 and 相对 == 键父:
                    continue
                路径 = 临根 / 相对
                路径.parent.mkdir(parents=True, exist_ok=True)
                路径.write_text(内容, encoding="utf-8")
            return 验证(临根)

    挂了, 没挂 = 跑(True), 跑(False)
    失败数 = lambda r: len([x for x in r["失败"] if isinstance(x, str)])  # noqa: E731
    出.append(
        (
            "对照：不挂载 ⇒ 同一份文件被抓到（证明「跳过」不是空转）",
            失败数(挂了) == 0 and 失败数(没挂) > 0,
            f"挂了：失败 {失败数(挂了)} 项 · 没挂：失败 {失败数(没挂)} 项 "
            f"{[x for x in 没挂['失败'] if isinstance(x, str)]}",
        )
    )
    return 出


def 自检_拓扑判据收窄() -> list:
    """⑪-3 / ⑪-4 两条判据**收窄后的形状**的身份证（2026-09-25 收窄）。

    为什么单列：这两条原先都靠「词」判（⑪-3 数 `载入(` 的任意出现 · ⑪-4 数 6 个中文词），
    词法判据必然把**枚举解构 / 文档串 / 调用点 / 同义词**算进去 ⇒ 假阳性
    （依据：项目文档/未完成事项.md #34 · 决策记录/2026-09-26_验证面的边界.md §7.2）。
    收窄最怕**收过头**：把真调用点一起毙掉，读数从「2 处假红」变成「0 处假红」——同样错。
    故每条都成对钉：**不该命中的形状必须 0 处** + **该命中的形状必须 1 处**。
    （判据的可信性.md §三.5：判据的解析器也是假绿来源，所以它自己也要有身份证。）
    """
    出 = []

    def 断言(名, 好, 说明):
        出.append((名, 好, 说明))

    # ── ⑪-3：`载入` 的调用点 ──
    真调用 = "let 表 = v1_loader::载入(声明, &台账).map_err(装载失败::载入)?;\n"
    解构_臂 = "match 结果 {\n    装载失败::载入(内) => 报(内),\n    _ => 好,\n}\n"
    解构_iflet = "if let 装载失败::载入(内) = 结果 { 报(内); }\n"
    定义 = "pub fn 载入(声明: &'static 平台信息) -> Result<注册表, 载入错误> { 好 }\n"
    变体声明 = "    载入(载入错误),\n"
    断言(
        "正向样本：真调用点 `v1_loader::载入(声明, &台账)`（带路径前缀）必须被数到",
        len(载入调用点(真调用)) == 1,
        f"数到 {len(载入调用点(真调用))} 处（要求 1）——带 `::` 前缀的真调用点不许被收窄毙掉",
    )
    断言(
        "反向样本：枚举解构（match 臂模式位 `装载失败::载入(内) =>`）不该被数成调用点",
        len(载入调用点(解构_臂)) == 0,
        f"数到 {len(载入调用点(解构_臂))} 处（要求 0）——这就是两条腿各自绕开的那处假阳性",
    )
    断言(
        "反向样本：`if let` 解构（`装载失败::载入(内) = …`）不该被数成调用点",
        len(载入调用点(解构_iflet)) == 0,
        f"数到 {len(载入调用点(解构_iflet))} 处（要求 0）——模式位不止 match 臂一种",
    )
    断言(
        "反向样本：定义形 `fn 载入(` 与枚举变体声明 `载入(载入错误),` 都不算调用点",
        len(载入调用点(定义)) == 0 and len(载入调用点(变体声明)) == 0,
        f"定义 {len(载入调用点(定义))} 处 · 变体声明 {len(载入调用点(变体声明))} 处（都要求 0）",
    )
    混 = 真调用 + 解构_臂 + 解构_iflet
    断言(
        "对照：真调用 + 两处解构混在一起 ⇒ 仍恰好 1 处（解构不许把读数抬起来）",
        len(载入调用点(混)) == 1,
        f"混装文里数到 {len(载入调用点(混))} 处（要求 1）——收窄前这里会数成 3 处",
    )

    # ── ⑪-4：资源唯一出入口（冻结访问形状）──
    真定义 = "pub fn 资源调用(&self, 资源号: u32, 操作号: u32, 输入槽表: &[数据槽]) -> 关口结果 {\n"
    改名定义 = "pub fn 另一条腿(资源号: u32, 操作号: u32, 输入槽表: &[数据槽]) -> 关口结果 {\n"
    文档串 = "//! 调：(资源号, 操作号, 输入槽表) → 输出槽表 | 结构化错误（`资源调用`）\n"
    调用点 = "let 结果 = 关口.资源调用(资源号, 操作号, 输入槽表);\n"
    私有助手 = "fn 派发(&self, 声明: Option<&资源声明>, 资源号: u32, 操作号: u32, 输入槽表: &[数据槽]) -> 关口结果 {\n"
    校形状 = "pub(super) fn 校输入形状(资源号: u32, 操作号: u32, 输入类型: u32, 输入槽表: &[数据槽]) -> Result<数据槽, 资源错误> {\n"
    断言(
        "正向样本：真出入口定义（§四 冻结访问形状）必须被数到",
        len(资源出入口形.findall(真定义)) == 1,
        f"数到 {len(资源出入口形.findall(真定义))} 处（要求 1）",
    )
    断言(
        "反向样本：文档串里的同名词（`//! 调：(资源号, 操作号, 输入槽表)`）不该被数成出入口",
        len(资源出入口形.findall(文档串)) == 0,
        f"数到 {len(资源出入口形.findall(文档串))} 处（要求 0）——原来这袋同义词连文档串都算",
    )
    断言(
        "反向样本：调用点 `关口.资源调用(资源号, 操作号, 输入槽表)` 不该被数成出入口",
        len(资源出入口形.findall(调用点)) == 0,
        f"数到 {len(资源出入口形.findall(调用点))} 处（要求 0）——出入口数**定义**，不数调用",
    )
    断言(
        "反向样本：私有助手（参数多一个 / 中间插了别的参数）不算第二个出入口",
        len(资源出入口形.findall(私有助手)) == 0 and len(资源出入口形.findall(校形状)) == 0,
        f"派发 {len(资源出入口形.findall(私有助手))} 处 · 校输入形状 {len(资源出入口形.findall(校形状))} 处（都要求 0）",
    )
    断言(
        "正向样本：**改名**的同一形状仍被抓（判据不认函数名）",
        len(资源出入口形.findall(改名定义)) == 1,
        f"数到 {len(资源出入口形.findall(改名定义))} 处（要求 1）——#34 的抱怨「换个命名就红」的反面",
    )
    混4 = 真定义 + 文档串 + 调用点 + 私有助手 + 校形状
    断言(
        "对照：真定义 + 文档串 + 调用点 + 私有助手混在一起 ⇒ 仍恰好 1 处",
        len(资源出入口形.findall(混4)) == 1,
        f"混装文里数到 {len(资源出入口形.findall(混4))} 处（要求 1）——收窄前这里会数成 3 处",
    )
    return 出


def 自检_前端语义判据() -> list:
    """⑪ 判据 6（前端零逻辑）**从词命中改成语义判**后的身份证（2026-09-27 收窄）。

    为什么单列：原模式 `JSON\\.parse|JSON\\.stringify|校验|解析|生成|validate|parse\\(` 是一袋词，
    它把 `前端呈现/网页应用/取接口.js` 里**传输必需的 `JSON.stringify(文本)`** 判成了违规
    （未完成事项.md #176）。收窄最怕**收过头**：把真解析一起放过 ⇒ 判据变成空转。
    故成对钉三层：
      · **反向样本**：注入一处**真 `JSON.parse`** ⇒ ⑪ 必须报红、且指到注入件；
      · **正向样本**：注入 `JSON.stringify` / 一段**解释自己不是违规的注释** / 纯拼接搬运 ⇒ 不许报红；
      · **承重证明（关/开对照）**：把判据临时关掉（模式换成永不匹配）再注入**同一处真解析**
        ⇒ 必须不报 —— 证明那处红**确实由本判据承重**，不是别的判据顺带报的。
    依据：项目文档/设计文档/判据的可信性.md §三.5（判据的解析器/模式也是假绿来源）。
    """
    import tempfile

    出 = []
    注入件 = "前端呈现/网页应用/注入样例.js"

    def 断言(名, 好, 说明):
        出.append((名, 好, 说明))

    # ── 第一层：纯文本（快，直接钉模式本身；样本取自现场实测的形状）──
    真解析 = 'export function 取值(文) { return JSON.parse(文); }\n'
    序列化 = 'export function 编码(文) { return JSON.stringify(文); }\n'
    辩解注释 = (
        "// `JSON.stringify` 只做编码：把文本编成 JSON 字面量，不改内容、不看内容。\n"
        "// 这里不解析、不校验 —— 任何判断都在后端。\n"
        "export function 编码(文) { return JSON.stringify(文); }\n"
    )
    搬运 = 'export function 拼(号, 文) { return "{" + 号 + ":" + 文 + "}"; }\n'
    词袋 = re.compile(r"JSON\.parse|JSON\.stringify|校验|解析|生成|validate|parse\(")

    def 命中(文, 模式=None):
        return [x.group(0) for x in (模式 or 前端逻辑模式).finditer(生产区文本(文))]

    断言(
        "反向样本：真 `JSON.parse` ⇒ 新模式报（解析 = 对内容作出判断）",
        bool(命中(真解析)),
        f"命中 {命中(真解析)}（要求非空）",
    )
    断言(
        "正向样本：`JSON.stringify` ⇒ 新模式不报（序列化是传输必需的编码）",
        not 命中(序列化),
        f"命中 {命中(序列化)}（要求空）——它不看内容、不改内容",
    )
    断言(
        "正向样本：一段「解释自己不是违规」的注释 ⇒ 新模式不报",
        not 命中(辩解注释),
        f"命中 {命中(辩解注释)}（要求空）——#176 的病灶就在这里",
    )
    断言(
        "对照：同一份文本，**原词袋模式**报（证明收窄真治了那个病）",
        bool(命中(辩解注释, 词袋)) and not 命中(辩解注释),
        f"原模式命中 {命中(辩解注释, 词袋)} · 新模式命中 {命中(辩解注释)}",
    )
    断言(
        "正向样本：纯拼接搬运（编码传输串）⇒ 不报",
        not 命中(搬运),
        f"命中 {命中(搬运)}（要求空）——纯搬运/编码允许",
    )
    断言(
        "反向样本：`DOMParser` / `eval(` / 正则 `.test(` 这类真判断 ⇒ 报",
        all(
            命中(x)
            for x in (
                "const 解 = new DOMParser();\n",
                "export function 跑(s) { return eval(s); }\n",
                "export function 判(s) { return /^[0-9]+$/.test(s); }\n",
            )
        ),
        "三种判断形各报一处（要求都非空）",
    )

    # ── 第二层：端到端（注入到干净合成仓 ⇒ 跑真判据；含关/开对照）──
    def 跑(注入文, 关判据=False):
        with tempfile.TemporaryDirectory(prefix="一键验证前端语义-") as 临时:
            临根 = Path(临时) / "仓"
            造干净仓(临根)
            if 注入文 is not None:
                (临根 / 注入件).write_text(注入文, encoding="utf-8")
            原模式 = globals()["前端逻辑模式"]
            try:
                if 关判据:
                    globals()["前端逻辑模式"] = re.compile(r"(?!)")  # 永不匹配 = 判据关掉
                return 验证(临根, 两遍=False)
            finally:
                globals()["前端逻辑模式"] = 原模式

    def 判据6条(结果):
        return [
            条
            for 条 in 结果["失败"] + 结果["未判"]
            if isinstance(条, dict) and 条["检查"] == 检查名[10] and "前端呈现" in 条["位置"]
        ]

    def 读数(结果):
        return [f"{条['位置']} ｜ {条['缺什么'][:70]}" for 条 in 判据6条(结果)]

    def 指到注入件(结果):
        return any(
            注入件 in 条["位置"] or 注入件 in 条["缺什么"] for 条 in 判据6条(结果)
        )

    开 = 跑(真解析)
    关 = 跑(真解析, 关判据=True)
    序列化果 = 跑(序列化)
    注释果 = 跑(辩解注释)
    基线 = 跑(None)

    断言(
        "反向样本（端到端）：干净仓 + 一处真 `JSON.parse` ⇒ ⑪ 判据 6 报红且指到注入件",
        len(判据6条(开)) == 1 and 指到注入件(开),
        f"⑪ 报 {len(判据6条(开))} 条：{读数(开)}",
    )
    断言(
        "承重证明（关/开对照）：判据关掉 + **同一处**真解析 ⇒ 不报",
        len(判据6条(关)) == 0,
        f"关掉后 ⑪ 报 {len(判据6条(关))} 条（要求 0）：{读数(关)}",
    )
    断言(
        "正向样本（端到端）：干净仓 + `JSON.stringify` ⇒ ⑪ 判据 6 不报",
        len(判据6条(序列化果)) == 0,
        f"⑪ 报 {len(判据6条(序列化果))} 条（要求 0）：{读数(序列化果)}",
    )
    断言(
        "正向样本（端到端）：干净仓 + 辩解注释 ⇒ ⑪ 判据 6 不报",
        len(判据6条(注释果)) == 0,
        f"⑪ 报 {len(判据6条(注释果))} 条（要求 0）：{读数(注释果)}",
    )
    断言(
        "基线：干净合成仓不注入 ⇒ ⑪ 判据 6 也不报（正向样本上不误报）",
        len(判据6条(基线)) == 0,
        f"⑪ 报 {len(判据6条(基线))} 条（要求 0）：{读数(基线)}",
    )
    return 出


def 自检_前端内联脚本() -> list:
    """⑪-6 的 `.html` 内联 `<script>` 扫描面的身份证（未完成事项.md #38）。

    反向样本：只含**内联** `<script>…JSON.parse(…)</script>` 的 `.html` ⇒ ⑪-6 必须报
    （证明内联脚本真进了扫描面）。
    正向样本：只含**外链** `<script src=…>`（外链由它自己的 `.js` 件覆盖），
    且**标记属性里**写了 `JSON.parse` 的字样 ⇒ ⑪-6 不报（证明只扫脚本体，不扫标记）。
    承重证明（关/开对照）：关掉 `前端逻辑模式` + 同一注入 ⇒ 不报。
    """
    import tempfile

    出 = []
    注入件 = "前端呈现/网页应用/注入样例.html"
    反向文 = '<html><body><script>const x = JSON.parse("{}");</script></body></html>\n'
    正向文 = (
        '<html><body data-注="JSON.parse( 只是标记属性里的字样，不是脚本">\n'
        '<script type="module" src="应用.js"></script></body></html>\n'
    )

    def 跑(html文, 关判据=False):
        with tempfile.TemporaryDirectory(prefix="一键验证前端内联-") as 临时:
            临根 = Path(临时) / "仓"
            造干净仓(临根)
            if html文 is not None:
                (临根 / 注入件).write_text(html文, encoding="utf-8")
            原模式 = globals()["前端逻辑模式"]
            try:
                if 关判据:
                    globals()["前端逻辑模式"] = re.compile(r"(?!)")  # 永不匹配 = 判据关掉
                return 验证(临根, 两遍=False)
            finally:
                globals()["前端逻辑模式"] = 原模式

    def 判据6条(结果):
        return [
            条
            for 条 in 结果["失败"] + 结果["未判"]
            if isinstance(条, dict) and 条["检查"] == 检查名[10] and "前端呈现" in 条["位置"]
        ]

    开 = 跑(反向文)
    关 = 跑(反向文, 关判据=True)
    正 = 跑(正向文)
    出.append(
        (
            "反向样本：`.html` 内联 `<script>` 里的真 `JSON.parse` ⇒ ⑪-6 报",
            len(判据6条(开)) >= 1,
            f"⑪ 报 {len(判据6条(开))} 条（要求 ≥1）",
        )
    )
    出.append(
        (
            "承重证明（关/开对照）：关掉 `前端逻辑模式` + 同一注入 ⇒ 不报",
            len(判据6条(关)) == 0,
            f"关掉后 ⑪ 报 {len(判据6条(关))} 条（要求 0）",
        )
    )
    出.append(
        (
            "正向样本：只含外链 `<script src=…>`（标记属性里有 `JSON.parse` 字样）⇒ 不报",
            len(判据6条(正)) == 0,
            f"⑪ 报 {len(判据6条(正))} 条（要求 0）——只扫脚本体，不扫标记",
        )
    )
    return 出


def 自检_临时件排除承重() -> list:
    """判据 ⑰ 的扫描面排除**承重证明**（关/开对照）。

    未完成事项.md #204：临时件落树里会让**别的**判据一起报假红（实测 ⑬ 报 9 条 · ⑮ 报 1 条）。
    本实现按 `_临时_` 前缀把临时件排除在扫描面外 —— 但「排除」本身也要有身份证：
      · 开着排除：注入 `_临时_` 临时根 ⇒ ⑬ / ⑮ 都不报（假红被挡住），⑰ 报（纪律仍钉住）；
      · 关掉排除（前缀换成永不匹配）：**同一注入** ⇒ ⑬ / ⑮ 必须报（证明排除真的在承重）。
    """
    import tempfile

    出 = []
    临时名 = 检查名[16]

    def 命中(结果, 名):
        return [
            条
            for 条 in 结果["失败"] + 结果["未判"]
            if isinstance(条, dict) and 条["检查"] == 名
        ]

    with tempfile.TemporaryDirectory(prefix="一键验证临时件承重-") as 临时:
        临根 = Path(临时) / "仓"
        造干净仓(临根)
        注入_临时件落源码树(临根)
        开 = 验证(临根, 两遍=False)
    出.append(
        (
            "反向样本：临时件在树里 ⇒ ⑰ 报（纪律钉住）",
            bool(命中(开, 临时名)),
            f"⑰ 报 {len(命中(开, 临时名))} 条（要求非空）",
        )
    )
    出.append(
        (
            "正向样本：临时件在树里 ⇒ ⑬ / ⑮ 都不报（扫描面排除生效）",
            not 命中(开, 检查名[12]) and not 命中(开, 检查名[14]),
            f"⑬ 报 {len(命中(开, 检查名[12]))} 条 · ⑮ 报 {len(命中(开, 检查名[14]))} 条（都要求 0）",
        )
    )
    # 关掉排除：同一注入，⑬ / ⑮ 必须报（先按正常前缀造好注入，再关排除重跑）
    with tempfile.TemporaryDirectory(prefix="一键验证临时件承重关-") as 临时:
        临根2 = Path(临时) / "仓"
        造干净仓(临根2)
        注入_临时件落源码树(临根2)
        原前缀 = globals()["临时目录前缀"]
        try:
            globals()["临时目录前缀"] = "\x00关掉排除"
            关 = 验证(临根2, 两遍=False)
        finally:
            globals()["临时目录前缀"] = 原前缀
    出.append(
        (
            "承重证明（关/开对照）：关掉排除 + 同一注入 ⇒ ⑬ / ⑮ 报（排除真的在挡假红）",
            bool(命中(关, 检查名[12])) or bool(命中(关, 检查名[14])),
            f"关掉后 ⑬ 报 {len(命中(关, 检查名[12]))} 条 · "
            f"⑮ 报 {len(命中(关, 检查名[14]))} 条（至少一个非空）",
        )
    )
    return 出


def 自检_并行生产区上下文() -> list:
    """元判据 ⑤「判据调 `并行生产区` 必须传全套上下文」的身份证（未完成事项.md #46）。

    为什么单列：漏传 `测试文件集` 时 `并行生产区` 用默认空集 ⇒ 整份夹具被当生产代码
    （实测 检查13 曾漏传 ⇒ 常量重定义假红）。这条判据的扫描器自己也要有正/反样本，
    否则它可能恒真（例如配平括号写错 ⇒ 永远取不到实参 ⇒ 永远不报）。
    """
    出 = []
    # 样本里的调用形状**拆开拼**（`名 + "("`）：本判据扫的是本文件自己的源码，
    # 源码里直接写一整条调用会被它读成一处**真调用** ⇒ 给判据面造假红
    # （同 `自检_整份夹具跳过` 把 Rust 形状拆开拼的先例）。
    名 = "并行生产区"
    正 = f'代码件 = {名}(扫描件源, 上["测试文件集"])\n'
    反 = f"代码件 = {名}(扫描件源)\n"
    反保串 = f"导出表 = {名}(扫描件源, 保串=True)\n"
    定义 = f"def {名}(件表, 测试文件集=frozenset(), 保串=False):\n    pass\n"
    出.append(
        (
            "正向样本：传了 `测试文件集` 的调用 ⇒ 不报",
            len(漏传上下文调用(正)) == 0,
            f"报 {len(漏传上下文调用(正))} 处（要求 0）",
        )
    )
    出.append(
        (
            "反向样本：漏传 `测试文件集`（含只传 `保串`）⇒ 报，且报出行号",
            len(漏传上下文调用(反)) == 1 and len(漏传上下文调用(反保串)) == 1,
            f"反 {len(漏传上下文调用(反))} 处 · 反保串 {len(漏传上下文调用(反保串))} 处（都要求 1）",
        )
    )
    出.append(
        (
            "正向样本：定义形不算调用（不许把 `def` 那一行报成漏传）",
            len(漏传上下文调用(定义)) == 0,
            f"报 {len(漏传上下文调用(定义))} 处（要求 0）",
        )
    )
    return 出


def 造最小仓(源仓根: Path, 临根: Path) -> None:
    """把一个仓整体复制到临时目录（自测与正向样本都用它，避免动真仓）。"""

    def 忽略(目录, 名字表):
        return {名 for 名 in 名字表 if 名 in {".git", "构建环境", "只读参考", "__pycache__"}}

    shutil.copytree(源仓根, 临根, ignore=忽略, dirs_exist_ok=True)


def 自测(源仓根: Path) -> int:
    """逐条判据跑「反向样本 + 正向样本」，并给出每条的身份证。"""
    import tempfile

    print("自测：逐条判据的身份证（反向样本必须报红且报对位置；正向样本必须通过）")
    print("")
    全过 = True
    命中表 = {}

    # ── 反向样本：注入到干净合成仓 ──
    for 名, 该报的检查, 注入, 该出现的路径 in 自测用例:
        with tempfile.TemporaryDirectory(prefix="一键验证反向样本-") as 临时:
            临根 = Path(临时) / "仓"
            造干净仓(临根)
            果 = 注入(临根)
            元数据覆盖 = 果 if isinstance(果, dict) else None
            结果 = 验证(临根, 元数据覆盖=元数据覆盖)
            退出码 = 0 if not 结果["失败"] else 1
            条表 = [条 for 条 in (结果["失败"] + 结果["未判"]) if isinstance(条, dict)]
            命中 = [条 for 条 in 条表 if 条["检查"] == 该报的检查]
            命中位置 = [条 for 条 in 命中 if 该出现的路径 in 条["位置"] or 该出现的路径 in 条["缺什么"]]
            理由合格 = [
                条
                for 条 in 命中位置
                if len(条["不能自愈"]) >= 30 and not any(话 in 条["不能自愈"] for 话 in 空话表)
            ]
            断言 = [
                ("① 退出码非 0", 退出码 != 0),
                (f"② 报出「{该报的检查}」且指到 {该出现的路径}", bool(命中位置)),
                ("③ 理由具体（≥30 字 · 不含空话）", bool(理由合格)),
            ]
            这轮过 = all(好 for _, 好 in 断言)
            全过 = 全过 and 这轮过
            命中表[该报的检查] = 命中表.get(该报的检查, 0) + (1 if 命中位置 else 0)
            print(f"【反向样本·{名}】→ {该出现的路径}    结果：{'过' if 这轮过 else '不过'}")
            for 名目, 好 in 断言:
                print(f"  {'✓' if 好 else '✗'} {名目}")
            for 条 in 命中位置[:2]:
                print(
                    f"  - {条['检查']} ｜ {条['位置']} ｜ 缺什么：{条['缺什么'][:120]} ｜ "
                    f"分类：{条.get('分类')}"
                )
            if not 命中位置:
                print("  实际：该判据没有报出这一条（断言②失败）")
            print("")

    # ── 正向样本：干净合成仓，不注入 ⇒ 所有判据必须通过 ──
    with tempfile.TemporaryDirectory(prefix="一键验证正向样本-") as 临时:
        临根 = Path(临时) / "仓"
        造干净仓(临根)
        结果 = 验证(临根)
    正过 = not 结果["失败"] and not 结果["未判"]
    全过 = 全过 and 正过
    print(f"【正向样本·干净合成仓】不注入任何东西    结果：{'过' if 正过 else '不过'}")
    print(
        f"  通过 {len(结果['通过'])} 项 · 失败 {len([x for x in 结果['失败'] if isinstance(x, str)])} 项 · "
        f"未判 {len([x for x in 结果['未判'] if isinstance(x, str)])} 项 · "
        f"疑似瞬时 {len(结果['疑似瞬时'])} 项"
    )
    if not 正过:
        for 条 in [x for x in 结果["失败"] + 结果["未判"] if isinstance(x, dict)][:6]:
            print(f"  ✗ 干净输入上仍报：{条['检查']} ｜ {条['位置']} ｜ 缺什么：{条['缺什么'][:160]}")
    print("")

    # ── 判据器自身机制的身份证：解析器也要有反向样本（判据的可信性.md §三.5）──
    print("判据器自身机制（判据的解析器也是假绿来源，所以它自己也要有身份证）：")
    机制用例 = (
        自检_剥字面量剥序()
        + 自检_整份夹具跳过()
        + 自检_拓扑判据收窄()
        + 自检_前端语义判据()
        + 自检_前端内联脚本()
        + 自检_临时件排除承重()
        + 自检_并行生产区上下文()
        + 自检_退出码语义()
    )
    for 名, 好, 说明 in 机制用例:
        全过 = 全过 and 好
        print(f"  {'✓' if 好 else '✗'} {名}")
        print(f"      {说明}")
    print("")

    # ── 身份证总表：每条判据都必须有反向样本与正向样本 ──
    print("判据身份证（每条判据 反向样本 + 正向样本）：")
    缺证 = []
    for 名, _函数 in 检查表:
        元 = 判据元数据.get(名, {})
        反 = 元.get("反向样本")
        正 = 元.get("正向样本")
        有反 = bool(反) and 反 in {x[0] for x in 自测用例}
        有正 = bool(正) and 正 == "干净合成仓"
        if not (有反 and 有正):
            缺证.append(名)
        print(f"  {'✓' if (有反 and 有正) else '✗'} {名}")
        print(f"      反向样本：{反 or '（无）'}    正向样本：{正 or '（无）'}")
    if 缺证:
        全过 = False
        print(f"  缺身份证的判据：{缺证}")
    print("")
    print(
        f"自测{'全部通过' if 全过 else '有不过的用例'}："
        f"{len(自测用例)} 个反向样本 + 1 个正向样本 · "
        f"判据器自身机制 {len(机制用例)} 条断言"
    )
    return 0 if 全过 else 1


# ════════════════════════════════════════════════════════════════════════════
# 入口
# ════════════════════════════════════════════════════════════════════════════


def 找仓根() -> Path:
    """仓根：本文件在 构建装配/一键验证/ 下 ⇒ 上溯两级。"""
    return Path(__file__).resolve().parents[2]


def 算退出码(结果: dict) -> int:
    """全过（无失败、无未判）= 0；否则 = 1。空集是「未判」不是「通过」。"""
    return 0 if not 结果["失败"] and not 结果["未判"] else 1


def 自检_退出码语义() -> tuple:
    """退出码语义：全过为零、未判不算过。

    反向样本就是本函数自己的历史缺陷：曾写成 `结果["失败"] == 0`，
    而它是 list ⇒ `[] == 0` 恒假 ⇒ 退出码恒 1（门禁报假红，读数与退出码相抵）。
    """
    return [
        ("退出码_全过为零", 算退出码({"失败": [], "未判": []}) == 0, "无失败无未判 ⇒ 0"),
        ("退出码_未判不算过", 算退出码({"失败": [], "未判": ["x"]}) == 1, "未判不是通过 ⇒ 1"),
        ("退出码_有失败为一", 算退出码({"失败": ["x"], "未判": []}) == 1, "有失败 ⇒ 1"),
    ]


def main(参数: list) -> int:
    仓根 = 找仓根()
    if not (仓根 / 契约目录名).is_dir():
        print(f"定位不到仓根：{仓根} 下没有 {契约目录名}/", file=sys.stderr)
        return 1
    if "--自测" in 参数:
        return 自测(仓根)
    结果 = 验证(仓根)
    打印(结果)
    if "--缺口" in 参数:
        print("")
        打印缺口()
    return 算退出码(结果)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
